      File(path)
          .writeAsString(
            jsonEncode({
              'capturedAtSec': DateTime.now().millisecondsSinceEpoch / 1000.0,
              'method': method,
              'url': url,
              'headers': sanitized,
              'body': body,
            }),
            flush: true,
          )
          .then((_) {}, onError: (Object _) {}),
    );
  }

  void emit(Map<String, Object?> event) {
    if (!_enabled) return;
    final line = _connPrefix + jsonEncode(event);
    final sink = emitSink;
    if (sink != null) {
      sink(line);
      return;
    }
    stderr.writeln(line);
    final path = _traceFilePath;
