Map<String, String> mergeProviderHeaders(
  Map<String, String> defaults,
  Map<String, String>? modelHeaders,
  Map<String, String?>? optionsHeaders,
) {
  final headers = <String, String>{...defaults, ...?modelHeaders};
  if (optionsHead…

