          .then((_) {}, onError: (Object _) {}),
    );
  }

  void emit(Map<String, Object?> event) {
    if (!_enabled) return;
    final line = _connPrefix + jsonEncode(event);
    final sink = emitSink;
    if (sink != null) {
      sink(line);
      return;
    }
    stderr.writeln(line);
    final path = _traceFilePath;
    if (path != null) {
      unawaited(
        File(path)
            .writeAsString('$line\n', mode: FileMode.append)
            .then((_) {}, onError: (Object _) {}),
      );
    }
  }
}

