bool hasHeader(Map<String, String?>? headers, String name) {
  if (headers == null) {
    return false;
  }
  final expected = name.toLowerCase();
  for (final entry in headers.entries) {
    final value = entry.value;
    if (entry.key.toLowerCase() == expected &&
        value != null &&
        value.trim().isNotEmpty) {
      return true;
    }
  }
  return false;
}

